mapper.select:
SELECT info.id as id, info.`name` AS `name`, info.`code` AS `code`, info.update_by as updateBy, info.update_time as updateTime, info.`enable` as `enable`, info.category_id as categoryId, info.description AS description, info.acquisition_platform FROM bp_equipment_info AS info JOIN bp_equipment_tag_info AS bp ON info.id = bp.equipment_id WHERE info.is_deleted = 0 AND bp.is_deleted = 0
and info.`name` like concat('%',#{name},'%')
and bp.tag_id in
#{item}
and info.`enable` =#{enable}
and info.category_id in
#{item}
GROUP BY info.id ORDER BY info.update_time desc

SELECT info.id, info.`code`, info.`name`, info.`status`, info.expire_date_time, station.station_id, info.acquisition_platform FROM bp_equipment_info AS info JOIN bp_equipment_station_info AS station ON info.id = station.equipment_id WHERE info.is_deleted = 0 AND station.is_deleted = 0
and station.station_id in
#{stationId}

SELECT distinct info.id, info.`code`, info.`name`, info.`status`, info.expire_date_time, info.acquisition_platform FROM bp_equipment_info AS info JOIN bp_equipment_station_info AS station ON info.id = station.equipment_id WHERE info.is_deleted = 0 AND station.is_deleted = 0
and station.station_id in
#{stationId}
